plugin.register('get_weather', async function (args, ctx) {
  var city = String((args && args.city) || '').trim();
  if (!city) return { error: '缺少参数 city，例如 {"city":"上海"}' };
  var g = await plugin.host.fetch('https://geocoding-api.open-meteo.com/v1/search?name='
    + encodeURIComponent(city) + '&count=1&language=zh&format=json');
  var gj = JSON.parse(g.text);
  var f = gj && gj.results && gj.results[0];
  if (!f) return { error: '查不到这个城市：' + city };
  var w = await plugin.host.fetch('https://api.open-meteo.com/v1/forecast?latitude=' + f.latitude
    + '&longitude=' + f.longitude
    + '&current=temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m'
    + '&timezone=auto');
  var c = (JSON.parse(w.text) || {}).current || {};
  return {
    city: f.name, country: f.country || '', lat: f.latitude, lon: f.longitude,
    temperature: c.temperature_2m, feelsLike: c.apparent_temperature,
    humidity: c.relative_humidity_2m, wind: c.wind_speed_10m, weatherCode: c.weather_code
  };
});
